import{_ as a,o as e,c as s,a2 as l}from"./chunks/framework.BbQrW5_t.js";const c=JSON.parse('{"title":"红队方向","description":"","frontmatter":{"title":"红队方向","date":"2026-09-03T00:00:00.000Z","tags":["网络安全","高级"]},"headers":[],"relativePath":"study/cyber-security/chapters/高级篇/01-红队方向.md","filePath":"study/cyber-security/chapters/高级篇/01-红队方向.md","lastUpdated":1788493831000}'),o={name:"study/cyber-security/chapters/高级篇/01-红队方向.md"};function r(i,t,d,n,h,u){return e(),s("div",null,[...t[0]||(t[0]=[l(`<h1 id="_01-·-红队方向——认知级攻击视角" tabindex="-1">01 · 红队方向——认知级攻击视角 <a class="header-anchor" href="#_01-·-红队方向——认知级攻击视角" aria-label="Permalink to &quot;01 · 红队方向——认知级攻击视角&quot;">​</a></h1><blockquote><p>红队的价值不在&quot;会用工具&quot;，而在<strong>模拟真实对手的完整思维</strong>。本章保持认知与防御视角：理解对手怎么想，才能知道蓝队该防什么、你该练什么。</p></blockquote><h2 id="🎯-学习目标" tabindex="-1">🎯 学习目标 <a class="header-anchor" href="#🎯-学习目标" aria-label="Permalink to &quot;🎯 学习目标&quot;">​</a></h2><ol><li>说清红队 / 渗透测试 / 漏洞赏金的角色差异</li><li>用 Kill Chain 与 ATT&amp;CK 双视角画出攻击生命周期</li><li>理解 EDR 的检测原理（&quot;被怎么看见&quot;）</li><li>制订 OSCP→CRTO 的认证路线</li></ol><h2 id="📖-核心知识" tabindex="-1">📖 核心知识 <a class="header-anchor" href="#📖-核心知识" aria-label="Permalink to &quot;📖 核心知识&quot;">​</a></h2><h3 id="_1-1-角色差异表" tabindex="-1">1.1 角色差异表 <a class="header-anchor" href="#_1-1-角色差异表" aria-label="Permalink to &quot;1.1 角色差异表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>角色</th><th>目标</th><th>交付</th><th>约束</th></tr></thead><tbody><tr><td>渗透测试</td><td>找漏洞证明风险</td><td>漏洞报告</td><td>范围明确，广泛扫描</td></tr><tr><td>红队</td><td>模拟 APT 检验<strong>防御体系</strong></td><td>攻击链复盘+检测缺口</td><td>隐蔽、低噪音、有交战规则(ROE)</td></tr><tr><td>漏洞赏金</td><td>单点漏洞变现</td><td>漏洞提交</td><td>平台 scope</td></tr></tbody></table><p>红队考核的是&quot;防守方能不能发现我&quot;，所以红队的核心产出常是<strong>检测缺口清单</strong>——对转行者的启示：懂攻击+懂蓝队研判=紫队，是护网里最抢手的复合角色。</p><h3 id="_1-2-攻击生命周期-双视角" tabindex="-1">1.2 攻击生命周期（双视角） <a class="header-anchor" href="#_1-2-攻击生命周期-双视角" aria-label="Permalink to &quot;1.2 攻击生命周期（双视角）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>阶段          红队做什么                蓝队该看见什么</span></span>
<span class="line"><span>侦察      被动收集(OSINT)              很难看见→攻击面收敛</span></span>
<span class="line"><span>初始访问  钓鱼/边界漏洞                邮件网关/WAF/IDS 告警</span></span>
<span class="line"><span>执行驻留  免杀载荷落地                 EDR 进程行为/AMSI</span></span>
<span class="line"><span>权限维持  计划任务/注册表/票据          持久化位置审计</span></span>
<span class="line"><span>横向移动  凭据滥用+远程服务            4688/网络登录异常</span></span>
<span class="line"><span>目标达成  数据外带/权限滥用            DLP/出站流量异常</span></span></code></pre></div><h3 id="_1-3-edr-视角-被怎么看见" tabindex="-1">1.3 EDR 视角：被怎么看见 <a class="header-anchor" href="#_1-3-edr-视角-被怎么看见" aria-label="Permalink to &quot;1.3 EDR 视角：被怎么看见&quot;">​</a></h3><p>EDR 的三板斧（理解它才能理解对抗的成本）：</p><ol><li><strong>用户态 Hook</strong>：API 调用被挂钩（如进程注入的 WriteProcessMemory 必经之路）</li><li><strong>ETW/内核遥测</strong>：进程/线程/网络/文件全事件流</li><li><strong>行为序列检测</strong>：单点不告警的&quot;可疑组合&quot;（如 Word→子进程 cmd→外连）</li></ol><p>因此现代对抗是&quot;成本游戏&quot;：绕过 EDR 的每种手法都在消耗红队的工程时间——<strong>蓝队只要提高对手成本就是赢</strong>。这也是为什么红队岗位要求开发能力：工具自研/魔改是核心竞争力（你的代码功底在此变现）。</p><h3 id="_1-4-c2-框架认知-概念" tabindex="-1">1.4 C2 框架认知（概念） <a class="header-anchor" href="#_1-4-c2-框架认知-概念" aria-label="Permalink to &quot;1.4 C2 框架认知（概念）&quot;">​</a></h3><p>C2 = 攻击者的&quot;指挥通信层&quot;：心跳（Beacon 回连）→ 指令下发 → 结果回传。认知要点：</p><ul><li>流量形态：固定间隔心跳/休眠抖动、域前置、DNS/ICMP 隐蔽信道（蓝队检测点见中级篇 08）</li><li>主流框架：Cobalt Strike（行业事实标准）、Sliver（开源）——<strong>仅在自有靶场授权演练</strong></li><li>红队基建思维：域名/载荷分发/重定向器的基础设施即代码</li></ul><h3 id="_1-5-认证与成长路线" tabindex="-1">1.5 认证与成长路线 <a class="header-anchor" href="#_1-5-认证与成长路线" aria-label="Permalink to &quot;1.5 认证与成长路线&quot;">​</a></h3><table tabindex="0"><thead><tr><th>阶段</th><th>认证</th><th>定位</th></tr></thead><tbody><tr><td>第 3 年主目标</td><td>OSCP</td><td>手活+报告的国际硬通货（24h 实操）</td></tr><tr><td>进阶</td><td>CRTO</td><td>红队操作（C2/对抗实操）</td></tr><tr><td>可选</td><td>CRTP/CRTL</td><td>AD 攻击专项</td></tr></tbody></table><p>OSCP 备考心法：PWK 课件 → Labs（≥50 台）→ 报告模板先行 → 考试时间盒管理（见第 3 年计划 W117-W128）。</p><h2 id="🔬-动手实操" tabindex="-1">🔬 动手实操 <a class="header-anchor" href="#🔬-动手实操" aria-label="Permalink to &quot;🔬 动手实操&quot;">​</a></h2><p>自建小型攻击模拟（全部自有环境）：Kali + Windows 10 虚拟机 → 用 open-source C2（如 Sliver）完成一次&quot;钓鱼 exe→回连→指令&quot;演练 → <strong>同时开 Sysmon 记录</strong> → 对照 1.2 表看&quot;蓝队本该在哪里看见你&quot;。</p><h2 id="⚠️-常见坑" tabindex="-1">⚠️ 常见坑 <a class="header-anchor" href="#⚠️-常见坑" aria-label="Permalink to &quot;⚠️ 常见坑&quot;">​</a></h2><ol><li>把红队当&quot;免杀炫技&quot;——价值在攻击链完整与检测缺口</li><li>C2 对接真实互联网——基础设施失控即违法</li><li>跳过蓝队视角——纯进攻思维在护网里反而吃瘪</li><li>OSCP 盲目报课——先 HTB 打到中上位再进 Labs 性价比更高</li><li>忽略交战规则（ROE）——红队第一份文件永远是规则书</li></ol><h2 id="✅-自测题" tabindex="-1">✅ 自测题 <a class="header-anchor" href="#✅-自测题" aria-label="Permalink to &quot;✅ 自测题&quot;">​</a></h2><details><summary>1. 红队与渗透测试最本质的区别？</summary><p>对象不同：渗透测&quot;系统漏洞&quot;，红队测&quot;防御体系有效性&quot;——红队假设漏洞存在，考核的是防守方能否检测与响应。</p></details><details><summary>2. EDR 行为序列检测的例子？</summary><p>Office 进程派生 cmd、cmd 发起外连、写入计划任务——单看每步都常见，组合即高危；规则表达为&quot;进程树+动作&quot;关联。</p></details><details><summary>3. 为什么说&quot;提高对手成本&quot;是防御的胜利？</summary><p>攻击者的对抗手法需工程投入（时间/技能/基础设施）；每抬高一分成本，低能力对手被挤出，剩下对手的频率与规模都下降。</p></details><details><summary>4. DNS 隐蔽信道为什么难封？</summary><p>DNS 是基础服务不能全禁；攻击把数据编码进子域名查询——只能靠熵值/频率异常检测而非简单封端口。</p></details><details><summary>5. ROE（交战规则）通常包含什么？</summary><p>范围（IP/域名/员工）、允许的强度（可否社工真实员工/可否致瘫）、时间窗、紧急联系人、数据处理要求。</p></details><h2 id="🔗-对应周任务与资源" tabindex="-1">🔗 对应周任务与资源 <a class="header-anchor" href="#🔗-对应周任务与资源" aria-label="Permalink to &quot;🔗 对应周任务与资源&quot;">​</a></h2><ul><li><strong>第3年 W105-W136</strong>；资源：The Hacker Playbook 3、Red Team Field Manual、MITRE ATT&amp;CK</li></ul>`,32)])])}const q=a(o,[["render",r]]);export{c as __pageData,q as default};
